#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<long long> sl(52, 0);
    sl[0] = 1;
    for (int i = 1; i <= 51; ++i) {
        sl[i] = sl[i - 1] + (1LL << i);
    }

    int h;
    long long n;
    cin >> h >> n;

    n += sl[h - 1];
    vector<long long> sequence;
    sequence.push_back(n);
    while (n > 1) {
        n /= 2;
        sequence.push_back(n);
    }

    long long total = 0;
    long long current = 1;
    bool flip = false;

    while (current != sequence[0]) {
        vector<long long> temp_list;
        long long temp = current;
        for (int i = 0; i < h; ++i) {
            temp_list.push_back(temp);
            if (!flip) {
                temp *= 2;
            } else {
                temp = temp * 2 + 1;
            }
            flip = !flip;
        }
        if (temp == sequence[0]) {
            total += h;
            break;
        }
        temp_list.push_back(temp);
        std::reverse(temp_list.begin(), temp_list.end());
        for (int i = 1; i <= h; ++i) {
            if (sequence[i] == temp_list[i]) {
                total += sl[i - 1] + h - i + 1;
                h = i - 1;
                current = temp_list[i - 1];
                if (current == temp_list[i] * 2) {
                    current = temp_list[i] * 2 + 1;
                    flip = false;
                } else {
                    current = temp_list[i] * 2;
                    flip = true;
                }
                break;
            }
        }
    }
    cout << total << "\n";
    return 0;
}
